import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  target = sys.argv[1] if len(sys.argv) > 1 else ""

  # Display progress message with colored output
  helpers.print_header(f"Zipping {target} to {target}.zip ...")

  # Create recursive zip archive
  run("zip", "--recurse-paths", f"{target}.zip", target)

  helpers.print_success(f"Backup completed: {target}.zip")


if __name__ == "__main__":
  main()
